%
\newcommand{\tarrow}[2]{\draw[->] (#1) -- (#2);}
\newcommand{\barrow}[2]{
  %
  \draw[->] (#1) -- (#2);
  \coordinate (temp1) at (xyz polar cs:angle=-20, radius=0.75);
  \coordinate (temp2) at (xyz polar cs:angle=210, radius=0.75);
  \coordinate (temp3) at (xyz polar cs:angle=255, radius=0.75);
