  \draw[->, \lightshade] (#1) -- ++(temp2);
  \draw[->, \lightshade] (#1) -- ++(temp3);
}
\newcommand{\carrowg}[3]{\draw[->, \relstyle, thick, \relcolor] (#1) to[bend right=#3] (#2);}
\newcommand{\carrow}[2]{\carrowg{#1}{#2}{45};}
%
%
%
\tikzset{n/.style = {circle, draw}}
\tikzset{im_n/.style = {}}
